# region: shape
def shape(raw):
    out = []
    for tok in raw[1:]:
        s = tok.strip()
        if s.isdigit() and int(s) > 0:
            out.append(int(s))
    return out

# region: emit
def emit(xs, offset=1):
    return [v + offset for v in xs]

# region: digest
def digest(xs, offset=1):
    return [v + offset for v in xs]

# region: intake
def intake(xs):
    return [v * v for v in xs]

# region: fold
def fold(xs):
    return {'n': len(xs), 'total': sum(xs)}

# region: gather
def gather(summary, name='gamma'):
    out = dict(summary)
    out['label'] = name.upper() if summary.get('n', 0) else 'EMPTY'
    return out

# region: run
def run(raw):
    return gather(fold(intake(digest(emit(shape(raw))))))

